s32 CVideo::MaxFrameRate(s32 fr)
{
	/* 0x308f20: sets the frame-rate cap (60 = none: -1) and returns the previous one */
	s32 old = m_maxFrameRate;
	m_maxFrameRate = fr == 60 ? -1 : fr;
	return old;
}

/* @socom-skeleton stub Fade__6CVideoFfUcUcUc */
void CVideo::Fade(float level, unsigned char r, unsigned char g, unsigned char b)
{
	/* 0x308ed0: the display's background colour and its blend level (zVid_Swap: alpha
	 * 0xff = picture only, lower blends towards the colour) */
	u8* bg = (u8*)&zvid.bgcolor;
	bg[0] = r;
	bg[1] = g;
	bg[2] = b;
	bg[3] = (u8)(unsigned int)(255.0f * level);
}

/* @socom-skeleton body RestoreImage__6CVideoFPc */
void CVideo::RestoreImage(char *img)
{
	/* 0x308c20: load a raw 640x448 frame into the render buffer in four GS image
	 * transfers (128, 128, 128 and 64 rows). */
	CFileIO file;

	if (file.Open(img))
	{
		void* buf = zmemalign(0x80, file.m_filesize);
		file.fread(buf, file.m_filesize);
		file.Close();

		short dbp = (short)zVid.renderBuf * 0x20;
		short dbw = (short)(zVid.renderWidth >> 6);
		sceGsLoadImage load[4];
		static const int rows[4] = {0x80, 0x80, 0x80, 0x40};

		for (int i = 0; i < 4; i++)
		{
			sceGsSetDefLoadImage(&load[i], dbp + i * 0x500, dbw, zvid.draw_psm, 0, 0, (short)zVid.renderWidth, rows[i]);
			FlushCache(0);
			sceDmaSync(zSys.DmaToGif, 0, 0);
			sceGsExecLoadImage(&load[i], (unsigned __int128*)((u8*)buf + i * 0x50000));
			sceGsSyncPath(0, 0);
		}

		zfree(buf);
	}
}

/* @socom-skeleton stub ReadGsMemory__6CVideoFUiP1Ui */
void CVideo::ReadGsMemory(unsigned int gsaddr, unsigned __int128 *buf, unsigned int size)
{
	/* 0x308ac0: GS memory back into main memory in 256 KB blocks (256 x 256 PSMCT32 from
	 * block address gsaddr), through VIF1 - its DMA (the MFIFO) held and restored */
	DIntr();
	*D1_CHCR &= 0xfeff;
	__asm__ volatile("sync.l");
	u32 chcr = *D1_CHCR;
	u32 tadr = *D1_TADR;
	u32 qwc = *D1_QWC;
	u32 madr = *D1_MADR;
	u32 ctrl = *D_CTRL;
	*D_CTRL = 1;
	sceGsSyncPath(0, 0);

	do
	{
		sceGsStoreImage store;
		sceGsSetDefStoreImage(&store, (short)gsaddr, 4, 0, 0, 0, 256, 256);
		FlushCache(0);
		sceGsExecStoreImage(&store, buf);
		size -= 0x40000;
		buf += 0x4000;
		gsaddr += 1024;
		sceGsSyncPath(0, 0);
	} while (size != 0);

	*D_CTRL = ctrl;
	*D1_MADR = madr;
	*D1_QWC = qwc;
	*D1_TADR = tadr;
	*D1_CHCR = chcr | 0x100;
	__asm__ volatile("sync.l");
	EIntr();
}

/* @socom-skeleton stub WriteGsMemory__6CVideoFUiP1Ui */
void CVideo::WriteGsMemory(unsigned int gsaddr, unsigned __int128 *buf, unsigned int size)
{
	/* 0x308a00: main memory into GS memory in 256 KB blocks (256 x 256 PSMCT32 at block
	 * address gsaddr) by PATH3 image transfers */
	DIntr();
	sceDmaSync(zSys.DmaToGif, 0, 0);

	do
	{
		sceGsLoadImage load;
		sceGsSetDefLoadImage(&load, (short)gsaddr, 4, 0, 0, 0, 256, 256);
		FlushCache(0);
		sceGsExecLoadImage(&load, buf);
		sceDmaSync(zSys.DmaToGif, 0, 0);
		size -= 0x40000;
		buf += 0x4000;
		gsaddr += 1024;
	} while (size != 0);

	EIntr();
}
